const CATEGORY_ORDER = [1,36,39,40,41,42,43,44,45,46];
const ROTATION_KEY = 'categoryRotationIndex';
const staticData = $getWorkflowStaticData('global');
let rotIdx = 0;
try { rotIdx = parseInt(staticData[ROTATION_KEY] || '0'); } catch(e) { rotIdx = 0; }
if (rotIdx >= CATEGORY_ORDER.length || rotIdx < 0) rotIdx = 0;
const currentCategoryId = CATEGORY_ORDER[rotIdx];

staticData[ROTATION_KEY] = String((rotIdx + 1) % CATEGORY_ORDER.length);

const categoryFeeds = CATEGORY_FEEDS[currentCategoryId] || CATEGORY_FEEDS[1];
const shuffled = [...categoryFeeds].sort(() => Math.random() - 0.5);
let feedData = '';
let feedUrl = '';
let errors = [];

for (let i = 0; i < Math.min(6, shuffled.length); i++) {
  try {
    const resp = await $http.get(shuffled[i], {
      timeout: 12000,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; TexasDadCooks/1.0)' }
    });
    const body = typeof resp === 'string' ? resp : (resp.data || resp.body || '');
    if (body && String(body).length > 300) {
      feedData = String(body);
      feedUrl = shuffled[i];
      break;
    }
  } catch(e) {
    errors.push(shuffled[i].substring(0,40) + ': ' + (e.message || 'failed').substring(0,50));
  }
}

return [{ json: { data: feedData, feedUrl: feedUrl, _feedErrors: errors, _currentCategoryId: currentCategoryId, _rotationIndex: rotIdx } }];

