if (!raw || raw.length < 150) {
  return [{ json: { ...trendData, articleHTML: '', category_id: forcedCatId, _hasContent: false } }];
}

const lines = raw.split('\n');
let title='', slug='', metaDesc='', tagsRaw='', excerpt='', imgQ0='', imgQ1='', imgQ2='', imgQ3='';
let articleStart = -1;

for (let i = 0; i < lines.length; i++) {
  const l = lines[i].trim();
  const t = l.toUpperCase();
  if (t.startsWith('TITLE:'))         title    = l.slice(6).trim();
  if (t.startsWith('SLUG:'))          slug     = l.slice(5).trim().toLowerCase().replace(/[^a-z0-9-]/g,'').substring(0,100);
  if (t.startsWith('META:'))          metaDesc = l.slice(5).trim().substring(0,155);
  if (t.startsWith('TAGS:'))          tagsRaw  = l.slice(5).trim();
  if (t.startsWith('EXCERPT:'))       excerpt  = l.slice(8).trim();
  if (t.startsWith('FEATURE_QUERY:'))  imgQ0    = l.slice(14).trim();
  if (t.startsWith('QUERY1:'))        imgQ1    = l.slice(7).trim();
  if (t.startsWith('QUERY2:'))        imgQ2    = l.slice(7).trim();
  if (t.startsWith('QUERY3:'))        imgQ3    = l.slice(7).trim();
  if (t.includes('START===')) { articleStart = i + 1; break; }
}

let articleHTML = '';
if (articleStart >= 0) {
  const rest = lines.slice(articleStart);
  const endIdx = rest.findIndex(l => l.toUpperCase().includes('END===') || l.toUpperCase().trim() === 'END');
  articleHTML = (endIdx >= 0 ? rest.slice(0, endIdx) : rest).join('\n').trim();
}
articleHTML = articleHTML.replace(/^```html\s*/i,'').replace(/^```\s*/,'').replace(/```\s*$/,'').trim();

const topicSafe = topicFallback.replace(/[^a-zA-Z0-9 ]/g,' ').split(' ').slice(0,3).join(' ');

const boostQ = (q, def) => {
  let c = (q || '').replace(/(?:Pixabay\s*|search\s*|for:\s*|\[|\])+/gi, '').trim();
  if (!c) c = topicSafe + ' ' + def;
  if (!c.toLowerCase().includes(topicSafe.split(' ')[0].toLowerCase())) c = topicSafe + ' ' + c;
  return c.substring(0, 100);
};

return [{ json: {
  ...trendData, 
  imgQuery0: boostQ(imgQ0, 'header'),
  imgQuery1: boostQ(imgQ1, 'dish'),
  imgQuery2: boostQ(imgQ2, 'ingredients'),
  imgQuery3: boostQ(imgQ3, 'cooking action'),
  title, articleHTML, category_id: forcedCatId, slug, metaDescription: metaDesc, excerpt, tags: tagsRaw.split(',').map(t=>t.trim()), _hasContent: articleHTML.length > 200
} }];

