  catch(e2) { d = $input.first().json; }
}

const cfg = $('Build Config').first().json;
const geminiKey = cfg._geminiKey || '';
const articleTopic = d.trendingTopic || d.title || 'cooking';
const usedImgIds = new Set();

// --- AI VISION VERIFICATION ---
async function verifyWithVision(topic, images) {
  if (!geminiKey || !images || images.length <= 1) return 0; // Skip if only 1 image or no key

  const prompt = `Task: You are an image editor for texasdadcooks.com.
Article Topic: "${topic}"

Candidates (URLs):
${images.map((img, i) => `${i + 1}. ${img.url}`).join('\n')}

Constraint: Pick the image that most ACCURATELY and PROFESSIONALLY represents the topic. Avoid generic or conceptually wrong matches (e.g. don't pick spices if the topic is pans).

Output: Return ONLY the index number (1, 2, or 3) of the winner.`;

  try {
    const resp = await $http.post(`https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash-latest:generateContent?key=${geminiKey}`, {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: 10, temperature: 0.1 }
    });
    const text = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
    const index = parseInt(text.replace(/[^0-9]/g, '')) - 1;
    return (index >= 0 && index < images.length) ? index : 0;
  } catch (e) {
    return 0; // Fallback to first image on error
  }
}

async function pickBestImage(nodeName, subTopic) {
  try {
    const apiResponse = $(nodeName).first().json;
    const hits = (apiResponse && apiResponse.hits) ? apiResponse.hits : [];
    const available = hits.filter(p => !usedImgIds.has(String(p.id))).slice(0, 3);

    if (available.length === 0) return null;
    if (available.length === 1) {
       const pick = available[0];
       usedImgIds.add(String(pick.id));
       return { url: pick.largeImageURL, alt: pick.tags, pName: pick.user, pUrl: `https://pixabay.com/users/${pick.user}-${pick.user_id}`, pgUrl: pick.pageURL };
    }

    // Vision Verification for top 3 candidates
    const candidates = available.map(p => ({ id: String(p.id), url: p.webformatURL || p.largeImageURL, raw: p }));
    const winIdx = await verifyWithVision(`${articleTopic} (${subTopic})`, candidates);
    const pick = available[winIdx];

    usedImgIds.add(String(pick.id));
    return {
      url: pick.largeImageURL || pick.webformatURL,
      alt: pick.tags,
      pName: pick.user,
      pUrl: `https://pixabay.com/users/${pick.user}-${pick.user_id}`,
      pgUrl: pick.pageURL
    };
  } catch(e) { return null; }
}

function makeImgBlock(img, headingText) {
  if (!img || !img.url) return '';
  const alt = (headingText + ' — texasdadcooks.com').replace(/"/g,"'").substring(0,120);
  const credit = `<p style="font-size:11px;color:#888;text-align:center;margin:5px 0 0;font-style:italic;">📷 Photo by <a href="${img.pUrl}" target="_blank">${img.pName}</a> on <a href="${img.pgUrl}" target="_blank">Pixabay</a></p>`;
  return `<figure style="margin:24px 0 32px;text-align:center;">\n<img src="${img.url}" alt="${alt}" width="800" height="450" style="width:100%;max-width:760px;height:auto;border-radius:10px;display:block;margin:0 auto;" loading="lazy"/>\n<figcaption>${credit}</figcaption>\n</figure>`;
}

let html = d.articleHTML || '';
const h2Regex = /(<h2[^>]*>[\s\S]*?<\/h2>)/gi;
const parts = html.split(h2Regex);
let result = '', h2Count = 0;

for (let i = 0; i < parts.length; i++) {
  const part = parts[i];
  if (/<h2/i.test(part)) {
    h2Count++;
    result += part.replace(/<h2/i, `<h2 id="sec-${h2Count}"`);

    let img = null;
    if (h2Count === 1) img = await pickBestImage('Fetch Inline Image 1 (Pixabay)', 'main dish');
    else if (h2Count === 3) img = await pickBestImage('Fetch Inline Image 2 (Pixabay)', 'ingredients');
    else if (h2Count === 5) img = await pickBestImage('Fetch Inline Image 3 (Pixabay)', 'cooking process');

    if (img) result += '\n' + makeImgBlock(img, part.replace(/<[^>]*>/g,'') || articleTopic);
  } else result += part;
}

return [{ json: { ...d, articleHTML: result } }];

const d = $json;
